/* Independent regular/thermal layout profiles, stored with business settings and backups. */
function customLayout(mode){let regular=mode!=='thermal',stored=db.settings.invoiceLayouts?.[mode]||{};return {enabled:false,width:regular?210:80,height:297,margin:regular?10:3,font:regular?12:11,spacing:regular?7:3,align:'left',logo:true,qr:true,stamp:true,bank:true,rate:true,itemDiscount:true,note:'',...stored}}
function validateCustomLayout(p,mode){let limits=mode==='thermal'?[48,112]:[100,330];if(!Number.isFinite(p.width)||p.width<limits[0]||p.width>limits[1])throw Error('Paper width must be '+limits[0]+'–'+limits[1]+' mm');if(mode!=='thermal'&&(!Number.isFinite(p.height)||p.height<140||p.height>500))throw Error('Paper height must be 140–500 mm');if(!Number.isFinite(p.margin)||p.margin<0||p.margin>Math.min(25,p.width/4))throw Error('Choose a smaller margin (maximum 25 mm or one-quarter of paper width).');if(!Number.isFinite(p.font)||p.font<8||p.font>18)throw Error('Font size must be 8–18 px');if(!Number.isFinite(p.spacing)||p.spacing<2||p.spacing>12)throw Error('Row spacing must be 2–12 px');return true}
function applyCustomLayout(sheet,p,mode){if(!sheet)return;sheet.classList.toggle('customizedInvoice',p.enabled);if(!p.enabled){for(let node of sheet.querySelectorAll('.customHidden'))node.classList.remove('customHidden');sheet.querySelector('.customInvoiceNote')?.remove();for(let property of ['--custom-width','--custom-font','--custom-space','--custom-align','--custom-margin'])sheet.style.removeProperty(property);if(mode==='thermal')sheet.style.setProperty('--receipt-width',(Number(db.settings.thermalWidth)===58?58:80)+'mm');return}sheet.dataset.customMode=mode;sheet.style.setProperty('--custom-width',(p.width-2*p.margin)+'mm');sheet.style.setProperty('--custom-font',p.font+'px');sheet.style.setProperty('--custom-space',p.spacing+'px');sheet.style.setProperty('--custom-align',p.align);sheet.style.setProperty('--receipt-width',p.width+'mm');sheet.style.setProperty('--invoice-paper-width',(p.width-2*p.margin)+'mm');sheet.style.setProperty('--custom-margin',p.margin+'mm');for(let [selector,shown]of [['.garageLogo',p.logo],['.invoiceQr,.thermalQr',p.qr],['.invoiceStamp,.thermalStamp',p.stamp],['.invoiceBankDetails',p.bank]])for(let node of sheet.querySelectorAll(selector))node.classList.toggle('customHidden',!shown);for(let table of sheet.querySelectorAll('table')){let head=table.tHead?.rows[0]||table.rows[0];if(!head)continue;for(let cell of head.cells){let title=cell.textContent.trim().toLowerCase(),show=title==='rate'?p.rate:title==='item discount'?p.itemDiscount:true;for(let row of table.rows)row.cells[cell.cellIndex]?.classList.toggle('customHidden',!show)}}sheet.querySelector('.customInvoiceNote')?.remove();if(p.note){let note=document.createElement('p');note.className='customInvoiceNote';note.textContent=p.note;sheet.appendChild(note)}}
function layoutFormMarkup(p,mode){return `<form id="customLayoutForm"><label class="customToggle"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}> Use this custom layout</label><div class="formgrid">${[{key:'width',label:'Paper Width (mm)'},...(mode==='thermal'?[]:[{key:'height',label:'Paper Height (mm)'}]),{key:'margin',label:'Margins (mm)'},{key:'font',label:'Font Size (px)'},{key:'spacing',label:'Row Spacing (px)'}].map(f=>field({...f,type:'number',required:true},p)).join('')}<label class="field"><span>Header Alignment</span><select name="align">${opts(['left','center','right'],p.align)}</select></label></div><div class="visibilityChoices">${[['logo','Show logo'],['qr','Show UPI QR'],['stamp','Show stamp / signature'],['bank','Show bank details'],...(mode==='thermal'?[]:[['rate','Show rate column'],['itemDiscount','Show item discount column']])].map(([key,label])=>`<label><input name="${key}" type="checkbox" ${p[key]?'checked':''}> ${label}</label>`).join('')}</div><label class="field"><span>Additional Footer Note</span><textarea name="note" maxlength="500">${esc(p.note)}</textarea></label><p id="customLayoutStatus" role="status"></p><div class="toolbar"><button class="btn" type="submit">Save Custom Layout</button><button class="btn secondary" type="button" id="restoreCustomLayout">Reset Layout</button></div></form>`}
function readLayoutForm(form,mode){let fd=new FormData(form),p=customLayout(mode);for(let key of ['width','height','margin','font','spacing'])if(fd.has(key))p[key]=Number(fd.get(key));for(let key of ['enabled','logo','qr','stamp','bank',...(mode==='thermal'?[]:['rate','itemDiscount'])])p[key]=fd.has(key);p.align=String(fd.get('align'));p.note=String(fd.get('note')||'');validateCustomLayout(p,mode);return p}
function openLayoutDesigner(mode,key,id){if(!key){key=db.jobs.length?'jobs':db.sales.length?'sales':null;id=key?db[key][0].id:null}let preview='';if(key&&id){if(mode==='thermal')openThermalInvoice(key,id);else invoice(key,id);preview=$('#modalBody '+(mode==='thermal'?'.thermalInvoice':'.invoice'))?.outerHTML||''}openModal('Customize '+(mode==='thermal'?'Thermal Receipt':'Regular Invoice'),`<div class="customLayoutDesigner"><div class="customLayoutOptions">${layoutFormMarkup(customLayout(mode),mode)}<p>Dimensions are in millimetres. Match the size in your printer driver. This custom layout applies to ${mode==='thermal'?'thermal receipts':'regular invoices'} when enabled.</p><p>The WhatsApp receipt image keeps its existing image layout.</p></div><div class="customLayoutPreview">${preview||'<p>Save a job card or sale to see a live invoice preview.</p>'}</div></div><div class="formactions">${key?'<button class="btn secondary" id="openDesignedInvoice" type="button">Open Invoice</button>':''}${btn('Close','cancel','secondary')}</div>`);let form=$('#customLayoutForm'),sample=$('#modalBody .customLayoutPreview '+(mode==='thermal'?'.thermalInvoice':'.invoice'));function paint(){try{let p=readLayoutForm(form,mode);let clean=preview?document.createElement('div'):null;if(clean){clean.innerHTML=preview;sample?.replaceWith(clean.firstElementChild);sample=$('#modalBody .customLayoutPreview '+(mode==='thermal'?'.thermalInvoice':'.invoice'));applyCustomLayout(sample,p,mode)}$('#customLayoutStatus').textContent='Preview updated. Save to use these settings.'}catch(err){$('#customLayoutStatus').textContent=err.message}}form.oninput=paint;form.onchange=paint;form.onsubmit=e=>{e.preventDefault();try{let p=readLayoutForm(form,mode),previous=structuredClone(db.settings);db.settings.invoiceLayouts={...db.settings.invoiceLayouts,[mode]:p};if(save('Custom invoice layout saved')===false){db.settings=previous;return}$('#customLayoutStatus').textContent='Saved. Open Invoice to print this layout.'}catch(err){$('#customLayoutStatus').textContent=err.message}};$('#restoreCustomLayout').onclick=()=>{let previous=structuredClone(db.settings);if(db.settings.invoiceLayouts)delete db.settings.invoiceLayouts[mode];if(save('Default layout restored')===false){db.settings=previous;return}openLayoutDesigner(mode,key,id)};if($('#openDesignedInvoice'))$('#openDesignedInvoice').onclick=()=>mode==='thermal'?openThermalInvoice(key,id):invoice(key,id);paint()}
function addLayoutButton(mode,key,id){let controls=$('#modalBody .invoiceFormatControls');if(!controls)return;let button=document.createElement('button');button.type='button';button.className='btn secondary';button.textContent='Customize Layout';button.onclick=()=>openLayoutDesigner(mode,key,id);controls.appendChild(button)}
const invoiceBeforeCustom=invoice;
invoice=function(key,id,paper){invoiceBeforeCustom(key,id,paper);applyCustomLayout($('#modalBody .invoice'),customLayout('regular'),'regular');addLayoutButton('regular',key,id)};
const thermalBeforeCustom=openThermalInvoice;
openThermalInvoice=function(key,id,width){thermalBeforeCustom(key,id,width);applyCustomLayout($('#modalBody .thermalInvoice'),customLayout('thermal'),'thermal');addLayoutButton('thermal',key,id);let original=$('#printThermalReceipt')?.onclick;if($('#printThermalReceipt'))$('#printThermalReceipt').onclick=()=>{let p=customLayout('thermal');if(!p.enabled)return original();printCustomInvoice('thermal',p)}};
const printBeforeCustom=printA4Invoice;
printA4Invoice=function(){let p=customLayout('regular');if(!p.enabled)return printBeforeCustom();printCustomInvoice('regular',p)};
function printCustomInvoice(mode,p){validateCustomLayout(p,mode);clearInvoicePrintMode();let style=document.createElement('style');style.id=mode==='thermal'?'thermalPageSize':'a4PageSize';style.textContent='@media print{@page{size:'+p.width+'mm '+(mode==='thermal'?'auto':p.height+'mm')+';margin:'+(mode==='thermal'?0:p.margin)+'mm}body.printingA4 .invoice.customizedInvoice{max-width:'+(p.width-2*p.margin)+'mm!important;width:'+(p.width-2*p.margin)+'mm!important}}';document.head.appendChild(style);document.body.classList.add(mode==='thermal'?'printingThermal':'printingA4');let cleanup=()=>{clearInvoicePrintMode();window.removeEventListener('afterprint',cleanup)};window.addEventListener('afterprint',cleanup);try{window.print()}catch{cleanup();toast('Use the browser print menu.')}}
const settingsBeforeCustom=settingsPage;
settingsPage=function(){return settingsBeforeCustom()+`<section class="panel"><div class="panelhead"><h2>Custom Invoice Layout Designer</h2></div><div class="panelbody"><p>Adjust paper dimensions, margins, font size, spacing, header alignment, optional sections and footer note. Regular invoices and thermal receipts have separate saved settings.</p><button type="button" class="btn" id="customizeRegularLayout">Customize Regular Invoice</button> <button type="button" class="btn secondary" id="customizeThermalLayout">Customize Thermal Receipt</button></div></section>`};
const renderBeforeCustom=render;
render=function(){renderBeforeCustom();if(page==='settings'){if($('#customizeRegularLayout'))$('#customizeRegularLayout').onclick=()=>openLayoutDesigner('regular');if($('#customizeThermalLayout'))$('#customizeThermalLayout').onclick=()=>openLayoutDesigner('thermal')}};
render();

